const {query} = require("../models/models");

const insertNotify = async (user_id, email, subject, message, error_message) => {
    let error_msg;

    if(!error_message){
        error_msg = " ";
    }else{
        error_msg = error_message;
    }

    try {
        const result = await query(`INSERT INTO notifications(user_id, email, subject, message, status, error_message)
            VALUES(?,?,?,?,?,?)
            `, [user_id, email, subject, message, "unreaded", error_msg])
        
        return result;
  } catch (err) {
    console.error('Erro ao enviar notificacao para', to, err && err.message);
    throw err;
  }
  
}

module.exports = insertNotify;